tape( 'the function handles large and small numbers', function test( t ) {
	var z1;
	var z2;
	var v;

	// Note: expected values were computed using Julia's `Complex{Float32}` division (here and in subsequent tests).

	z1 = new Complex64( 1.0e38, 5.0e37 );
	z2 = new Complex64( 1.0, 0.5 );
	v = div( z1, z2 );
	t.strictEqual( realf( v ), f32( 1.0e38 ), 'returns expected value' );
	t.strictEqual( isPositiveZerof( imagf( v ) ), true, 'returns expected value' );

	z1 = new Complex64( 1.0, 0.5 );
	z2 = new Complex64( 1.0e38, 5.0e37 );
	v = div( z1, z2 );
	t.strictEqual( realf( v ), f32( 1.0000001e-38 ), 'returns expected value' );
	t.strictEqual( isPositiveZerof( imagf( v ) ), true, 'returns expected value' );

	z1 = new Complex64( 1.0e-38, 2.0e-38 );
	z2 = new Complex64( 1.0, 2.0 );
	v = div( z1, z2 );
	t.strictEqual( realf( v ), f32( 1.0e-38 ), 'returns expected value' );
	t.strictEqual( isPositiveZerof( imagf( v ) ), true, 'returns expected value' );

	z1 = new Complex64( 1.0, 2.0 );
	z2 = new Complex64( 1.0e-38, 2.0e-38 );
	v = div( z1, z2 );
	t.strictEqual( realf( v ), f32( 1.0e38 ), 'returns expected value' );
	t.strictEqual( imagf( v ), f32( -2.802597e30 ), 'returns expected value' );

	z1 = new Complex64( 2.0, 4.0 );
	z2 = new Complex64( 0.0, 2.0 );
	v = div( z1, z2 );
	t.strictEqual( realf( v ), 2.0, 'returns expected value' );
	t.strictEqual( imagf( v ), -1.0, 'returns expected value' );

	z1 = new Complex64( 1.0e-20, 1.0e-20 );
	z2 = new Complex64( 1.0, 1.0e-20 );
	v = div( z1, z2 );
	t.strictEqual( realf( v ), f32( 1.0e-20 ), 'returns expected value' );
	t.strictEqual( imagf( v ), f32( 1.0e-20 ), 'returns expected value' );

	t.end();
});

tape( 'the function handles equal-magnitude denominator components', function test( t ) {
	var z1;
	var z2;
	var v;

	z1 = new Complex64( 7.0, 3.0 );
	z2 = new Complex64( 5.0, 5.0 );
	v = div( z1, z2 );
	t.strictEqual( realf( v ), 1.0, 'returns expected value' );
	t.strictEqual( imagf( v ), f32( -0.4 ), 'returns expected value' );

	z1 = new Complex64( 7.0, 3.0 );
	z2 = new Complex64( 5.0, -5.0 );
	v = div( z1, z2 );
	t.strictEqual( realf( v ), f32( 0.4 ), 'returns expected value' );
	t.strictEqual( imagf( v ), 1.0, 'returns expected value' );

	z1 = new Complex64( 1.0, 1.0 );
	z2 = new Complex64( 1.0, 1.0 );
	v = div( z1, z2 );
	t.strictEqual( realf( v ), 1.0, 'returns expected value' );
	t.strictEqual( isPositiveZerof( imagf( v ) ), true, 'returns expected value' );

	t.end();
});

tape( 'the function handles purely real and purely imaginary operands', function test( t ) {
	var z1;
	var z2;
	var v;

	z1 = new Complex64( 6.0, 0.0 );
	z2 = new Complex64( 3.0, 0.0 );
	v = div( z1, z2 );
	t.strictEqual( realf( v ), 2.0, 'returns expected value' );
	t.strictEqual( isPositiveZerof( imagf( v ) ), true, 'returns expected value' );

	z1 = new Complex64( 0.0, 6.0 );
	z2 = new Complex64( 0.0, 3.0 );
	v = div( z1, z2 );
	t.strictEqual( realf( v ), 2.0, 'returns expected value' );
	t.strictEqual( isPositiveZerof( imagf( v ) ), true, 'returns expected value' );

	z1 = new Complex64( 6.0, 0.0 );
	z2 = new Complex64( 0.0, 3.0 );
	v = div( z1, z2 );
	t.strictEqual( isPositiveZerof( realf( v ) ), true, 'returns expected value' );
	t.strictEqual( imagf( v ), -2.0, 'returns expected value' );

	z1 = new Complex64( 5.0, 3.0 );
	z2 = new Complex64( 0.0, 2.0 );
	v = div( z1, z2 );
	t.strictEqual( realf( v ), 1.5, 'returns expected value' );
	t.strictEqual( imagf( v ), -2.5, 'returns expected value' );

	z1 = new Complex64( 5.0, 3.0 );
	z2 = new Complex64( -2.0, 1.0 );
	v = div( z1, z2 );
	t.strictEqual( realf( v ), f32( -1.4 ), 'returns expected value' );
	t.strictEqual( imagf( v ), f32( -2.2 ), 'returns expected value' );

	t.end();
});

